import { loadFont as loadBlack } from "@remotion/google-fonts/ArchivoBlack";
import { loadFont as loadArchivo } from "@remotion/google-fonts/Archivo";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// ACELERA IGREJAS — anúncio do Leonardo Fonseca, v3 feita do zero (teste interno do o diretor, 10/11).
// Pedido: "bem impactante, bem agressivo, no máximo 1 minuto, música agressiva e motion agressivo".
// Material: um vídeo só (ele falando, IMG_8075) e o logo na parede atrás dele → jeito "motion": o vídeo dele entra
// como destaque nas falas diretas (pastor, nome, chamada) e o resto é desenhado (≈2/3 do vídeo).
// Identidade: o azul elétrico do logo + preto, branco e um ciano de destaque. Letra larga e pesada (Archivo Black)
// para o tom agressivo; Archivo 800 nas linhas de apoio.
// Elemento-fio: a barra inclinada do "A" do logo. Ela corta a tela nas trocas (cortina inclinada), monta o logo,
// vira a seta que rompe o ciclo e sobe no gráfico, e no fim o botão cresce e vira a tela final.
// Técnicas: texto subindo da máscara palavra por palavra, molas com pouco overshoot, cena que já entra em movimento,
// inundação de cor, câmera que viaja entre os números (com desfoque de movimento), gráfico que se desenha.
// Fala: o corte já feito (public/acelera/aroll.mp4, 59,47 s); tempos das palavras conferidos na transcrição.

const { fontFamily: H } = loadBlack("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: S } = loadArchivo("normal", { weights: ["600", "800"], subsets: ["latin", "latin-ext"] });

export const A3_FPS = 30;
// v6: a abertura volta a ser a gravação desde o quadro 0 (fita na boca); o resto da v5 anda 35 quadros
const OFF_F = 35;
export const A3_FRAMES = Math.round(60.6 * A3_FPS) + OFF_F;
const BLUE = "#3550FF";
const CYAN = "#22D3FF";
const INK = "#07080F";
const PALE = "#EEF0FF";
const WHITE = "#FFFFFF";
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN = Easing.bezier(0.7, 0, 0.84, 0);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const ease = (t: number, a: number, d = 0.3, e = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: e });
// mola: amortecida (texto) ou com ~3% de passada (objetos que pulam do zero)
const sp = (t: number, at: number, damping = 200, stiffness = 170) => (t < at ? 0 : spring({ fps: 30, frame: (t - at) * 30, config: { damping, stiffness, mass: 1 } }));
const pop = (t: number, at: number) => sp(t, at, 18, 140);

// ---------- texto ----------
// palavra por palavra subindo de dentro de uma máscara; sai descendo pela mesma máscara; tarja opcional que corre
// da esquerda antes da palavra e recolhe para a direita na saída
const Rise: React.FC<{ t: number; at: number; out?: number; size: number; color?: string; font?: string; ls?: number; bar?: string; stagger?: number; children: string }> = ({ t, at, out, size, color = WHITE, font = H, ls = 0, bar, stagger = 0.1, children }) => {
  const words = children.split(" ");
  const q = out !== undefined ? ease(t, out, 0.16, IN) : 0;
  const bw = bar ? sp(t, at - 0.08, 26, 190) : 0;
  return (
    <div style={{ position: "relative", display: "flex", gap: size * 0.27, padding: bar ? `${size * 0.04}px ${size * 0.24}px` : 0 }}>
      {bar ? <div style={{ position: "absolute", inset: 0, background: bar, transform: `scaleX(${(bw * (1 - q)).toFixed(4)})`, transformOrigin: q > 0 ? "100% 50%" : "0% 50%" }} /> : null}
      {words.map((w, i) => {
        const p = sp(t, at + i * stagger);
        return (
          <div key={i} style={{ position: "relative", overflow: "hidden", height: size * 1.3, display: "flex", alignItems: "center" }}>
            <div style={{ fontFamily: font, fontWeight: font === S ? 800 : 400, fontSize: size, lineHeight: 1.3, color, letterSpacing: ls ? `${ls}em` : undefined, whiteSpace: "nowrap", transform: `translateY(${((1 - p) * 105 + q * 105).toFixed(2)}%)` }}>{w}</div>
          </div>
        );
      })}
    </div>
  );
};
const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode }> = ({ top, gap = 0, children }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);
// bloco de lettering no peito de quem fala (termina em y 1450)
const Peito: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ position: "absolute", left: 120, right: 120, bottom: 1920 - 1450, display: "flex", flexDirection: "column", alignItems: "center", gap: 8 }}>{children}</div>
);
const win = (t: number, a: number, b: number) => t >= a && t < b;

// brilho só atrás do destaque
const Glow: React.FC<{ cy: number; c?: string; o?: number }> = ({ cy, c = "53,80,255", o = 0.35 }) => (
  <AbsoluteFill style={{ background: `radial-gradient(ellipse 65% 32% at 50% ${((cy / 1920) * 100).toFixed(1)}%, rgba(${c},${o}) 0%, rgba(${c},0) 70%)` }} />
);
// câmera reta que aproxima a cena inteira
const Push: React.FC<{ t: number; a: number; b: number; k?: number; oy?: number; children: React.ReactNode }> = ({ t, a, b, k = 0.07, oy = 50, children }) => (
  <AbsoluteFill style={{ transform: `scale(${(1 + k * lin(t, a, b)).toFixed(4)})`, transformOrigin: `50% ${oy}%` }}>{children}</AbsoluteFill>
);

// ---------- peças ----------
// logo oficial do cliente (src/pedido-1111, sem o preto) num cartão escuro: o "E" e o IGREJAS são azuis e sumiriam no
// fundo azul. Entra com mola e a logo se revela da esquerda para a direita (sem redesenhar nada)
const Marca: React.FC<{ t: number; at: number; w: number }> = ({ t, at, w }) => {
  const p = pop(t, at), r = ease(t, at + 0.08, 0.45);
  return (
    <div style={{ background: INK, borderRadius: 36, padding: "44px 50px", transform: `scale(${p.toFixed(4)})`, boxShadow: "0 24px 70px rgba(7,8,15,0.45)" }}>
      <Img src={staticFile("acelera/logo-oficial.png")} style={{ width: w, display: "block", clipPath: `inset(0 ${((1 - r) * 100).toFixed(1)}% 0 0)` }} />
    </div>
  );
};
const Cadeado: React.FC<{ t: number; at: number; close: number }> = ({ t, at, close }) => {
  const p = pop(t, at);
  const c = sp(t, close, 20, 220);
  return (
    <svg width={320} height={400} viewBox="0 0 320 400" style={{ transform: `scale(${p.toFixed(4)})`, overflow: "visible" }}>
      <path d="M85 190 V120 A75 75 0 0 1 235 120 V190" fill="none" stroke={WHITE} strokeWidth={36} strokeLinecap="round" transform={`translate(0 ${((1 - c) * -70).toFixed(1)})`} />
      <rect x={20} y={170} width={280} height={220} rx={36} fill={WHITE} />
      <circle cx={160} cy={262} r={26} fill={BLUE} />
      <rect x={148} y={270} width={24} height={60} rx={10} fill={BLUE} />
    </svg>
  );
};
const Casa: React.FC<{ x: number; y: number; on: number; lit: number }> = ({ x, y, on, lit }) => (
  <g transform={`translate(${x} ${y + (1 - on) * 40})`} opacity={on}>
    <path d="M0 42 L50 4 L100 42 V100 H0 Z" fill="none" stroke="rgba(160,172,255,0.55)" strokeWidth={6} strokeLinejoin="round" />
    <rect x={36} y={52} width={28} height={28} rx={4} fill={lit > 0 ? CYAN : "rgba(160,172,255,0.25)"} opacity={0.3 + 0.7 * lit} />
  </g>
);
const Balao: React.FC<{ x: number; y: number; p: number }> = ({ x, y, p }) => (
  <g transform={`translate(${x} ${y}) scale(${p.toFixed(3)})`}>
    <path d="M-40 -36 H40 A14 14 0 0 1 54 -22 V18 A14 14 0 0 1 40 32 H-6 L-22 50 L-20 32 H-40 A14 14 0 0 1 -54 18 V-22 A14 14 0 0 1 -40 -36 Z" fill={WHITE} />
    <text x={0} y={18} textAnchor="middle" fontFamily={H} fontSize={50} fill={BLUE}>?</text>
  </g>
);
// poltrona de auditório, de frente
const Poltrona: React.FC<{ x: number; y: number; s: number; on: number; o: number }> = ({ x, y, s, on, o }) => (
  <g transform={`translate(${x} ${y + (1 - on) * 50}) scale(${s})`} opacity={on * o}>
    <rect x={-46} y={-70} width={92} height={78} rx={22} fill="none" stroke={WHITE} strokeWidth={7} />
    <rect x={-56} y={8} width={112} height={30} rx={12} fill="none" stroke={WHITE} strokeWidth={7} />
    <path d="M-62 -10 V44 M62 -10 V44" stroke={WHITE} strokeWidth={7} strokeLinecap="round" />
  </g>
);

// ---------- transições ----------
// cortina inclinada: a barra do "A" atravessa a tela e cobre tudo no instante da troca
const Slash: React.FC<{ t: number; at: number; c: string }> = ({ t, at, c }) => {
  if (t < at - 0.26 || t > at + 0.26) return null;
  const p = interpolate(t, [at - 0.26, at + 0.26], [-1, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ pointerEvents: "none", overflow: "hidden" }}>
      <div style={{ position: "absolute", left: 540 - 1000, top: 960 - 2200, width: 2000, height: 4400, background: c, transform: `rotate(-28deg) translateX(${(p * 2900).toFixed(1)}px)` }} />
    </AbsoluteFill>
  );
};
type Tr = "cut" | "slash" | "iris" | "pushUp" | "pushLeft" | "panUp" | "zoom";
const TD: Record<Tr, number> = { cut: 0, slash: 0, iris: 0.45, pushUp: 0.4, pushLeft: 0.4, panUp: 0.4, zoom: 0.3 };
// estilo da cena que sai (X) e da que entra (Y) numa troca
const sai = (t: number, T: number, tr: Tr): React.CSSProperties | null => {
  const d = TD[tr];
  if (t >= T + d) return null;
  if (t < T) return {};
  const e = ease(t, T, d, INOUT);
  if (tr === "pushUp") return { transform: `translateY(${(-1920 * e).toFixed(1)}px)` };
  if (tr === "pushLeft") return { transform: `translateX(${(-1080 * e).toFixed(1)}px)` };
  if (tr === "panUp") return { transform: `translateY(${(1920 * e).toFixed(1)}px)` };
  if (tr === "zoom") return { transform: `scale(${(1 + 1.6 * e).toFixed(4)})`, opacity: 1 - e, filter: `blur(${(12 * e).toFixed(1)}px)`, zIndex: 5 };
  if (tr === "iris") return {};
  return null;
};
const entra = (t: number, T: number, tr: Tr, cx = 540, cy = 960): React.CSSProperties => {
  const d = TD[tr];
  if (t >= T + d || d === 0) return {};
  const e = ease(t, T, d, INOUT);
  if (tr === "pushUp") return { transform: `translateY(${(1920 * (1 - e)).toFixed(1)}px)` };
  if (tr === "pushLeft") return { transform: `translateX(${(1080 * (1 - e)).toFixed(1)}px)` };
  if (tr === "panUp") return { transform: `translateY(${(-1920 * (1 - e)).toFixed(1)}px)` };
  if (tr === "zoom") return { transform: `scale(${(1.15 - 0.15 * e).toFixed(4)})` };
  if (tr === "iris") return { clipPath: `circle(${(1150 * ease(t, T, d, OUT)).toFixed(1)}px at ${cx}px ${cy}px)`, zIndex: 4 };
  return {};
};

// ---------- a fala dele (destaque) ----------
const CUTS = [0, 4.7333, 11.1, 17.5, 23.3333, 31.5333, 34.6333, 39.1333, 45.3667, 47.03, 53.1, 55.2, 56.73, 58.43];
const END = 59.47;
const segAt = (t: number) => {
  let i = 0;
  for (let k = 0; k < CUTS.length; k++) if (CUTS[k] <= t + 1e-4) i = k;
  return i;
};
const Fala: React.FC<{ t: number }> = ({ t }) => {
  const i = segAt(t);
  // aproxima a partir da base do quadro: o rosto sobe e o queixo fica acima das tarjas do peito (pedido, 11/11)
  // no trecho do "resultado disso?" (17,5–23,3) ele está mais baixo no quadro: aproxima mais
  const z = (i === 3 ? 1.38 : i % 2 ? 1.24 : 1.14) + 0.03 * lin(t, CUTS[i], CUTS[i + 1] ?? END);
  return (
    <AbsoluteFill style={{ background: INK, overflow: "hidden" }}>
      <OffthreadVideo src={staticFile("acelera/aroll.mp4")} muted style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", transform: `scale(${z.toFixed(4)})`, transformOrigin: "50% 100%" }} />
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(7,8,15,0) 52%, rgba(7,8,15,0.55) 72%, rgba(7,8,15,0.85) 100%)" }} />
      {win(t, 4.75, 7.3) ? <Peito><Rise t={t} at={4.8} out={7.12} size={120} bar={BLUE}>PASTOR,</Rise></Peito> : null}
      {win(t, 7.25, 9.7) ? (
        <Peito>
          <Rise t={t} at={7.34} out={9.52} size={100} bar={BLUE}>PODE MUDAR</Rise>
          <Rise t={t} at={7.68} out={9.52} size={80} bar={WHITE} color={INK}>COMPLETAMENTE</Rise>
        </Peito>
      ) : null}
      {win(t, 9.65, 11.1) ? (
        <Peito>
          <Rise t={t} at={9.74} size={84} bar={WHITE} color={INK}>O CRESCIMENTO</Rise>
          <Rise t={t} at={10.44} size={84} bar={BLUE}>DA TUA IGREJA</Rise>
        </Peito>
      ) : null}
      {win(t, 17.5, 18.9) ? (
        <Peito>
          <Rise t={t} at={17.57} size={110} bar={WHITE} color={INK}>RESULTADO</Rise>
          <Rise t={t} at={18.17} size={110} bar={CYAN} color={INK}>DISSO?</Rise>
        </Peito>
      ) : null}
      {win(t, 31.53, 33.1) ? <Peito><Rise t={t} at={31.81} size={72} bar={BLUE}>A GENTE CONSEGUE</Rise></Peito> : null}
      {win(t, 39.13, 43.1) ? (
        <Peito>
          <Rise t={t} at={39.58} out={42.95} size={110} bar={WHITE} color={INK}>LEONARDO</Rise>
          <Rise t={t} at={40.0} out={42.95} size={110} bar={BLUE}>FONSECA</Rise>
          <div style={{ height: 6 }} />
          <Rise t={t} at={41.22} out={42.95} size={38} font={S} ls={0.08} stagger={0.05}>FUNDADOR · ACELERA IGREJAS</Rise>
        </Peito>
      ) : null}
      {win(t, 43.1, 44.8) ? (
        <Peito>
          <Rise t={t} at={43.17} size={90} bar={BLUE}>QUERO AJUDAR</Rise>
          <Rise t={t} at={43.83} size={110} bar={WHITE} color={INK}>TUA IGREJA</Rise>
        </Peito>
      ) : null}
      {win(t, 53.1, 54.3) ? (
        <Peito>
          <Rise t={t} at={53.15} out={54.12} size={100} bar={WHITE} color={INK}>QUER SABER</Rise>
          <Rise t={t} at={53.65} out={54.12} size={100} bar={BLUE}>MAIS?</Rise>
        </Peito>
      ) : null}
      {win(t, 55.2, 56.8) ? (
        <Peito>
          <Rise t={t} at={55.24} out={56.6} size={54} font={S} stagger={0.1}>NÃO É MAIS HORA DE</Rise>
          <Rise t={t} at={55.9} out={56.6} size={92} bar={BLUE}>PROCRASTINAR</Rise>
        </Peito>
      ) : null}
      {win(t, 56.75, 58.45) ? (
        <Peito>
          <Rise t={t} at={56.82} out={58.28} size={76} bar={WHITE} color={INK}>A OPORTUNIDADE</Rise>
          <Rise t={t} at={57.72} out={58.28} size={90} bar={CYAN} color={INK}>NA SUA FRENTE</Rise>
        </Peito>
      ) : null}
      <Botao t={t} a={54.33} b={55.12} />
      <Botao t={t} a={58.46} b={61} morph={58.9} />
    </AbsoluteFill>
  );
};
// botão "clica no link" no peito; no fim ele cresce e vira a tela final (azul)
const Botao: React.FC<{ t: number; a: number; b: number; morph?: number }> = ({ t, a, b, morph }) => {
  if (t < a || t >= b) return null;
  const p = pop(t, a);
  const x = b < 61 ? ease(t, b - 0.14, 0.14, IN) : 0;
  const m = morph ? ease(t, morph, 0.4, INOUT) : 0;
  const L = interpolate(m, [0, 1], [150, 0]), T = interpolate(m, [0, 1], [1270, 0]);
  const W = interpolate(m, [0, 1], [780, 1080]), Hh = interpolate(m, [0, 1], [160, 1920]), R = interpolate(m, [0, 1], [80, 0]);
  return (
    <div style={{ position: "absolute", left: L, top: T, width: W, height: Hh, borderRadius: R, background: BLUE, display: "flex", alignItems: "center", justifyContent: "center", gap: 22, transform: m > 0 ? undefined : `scale(${(p * (1 - x)).toFixed(4)})`, boxShadow: m > 0.5 ? "none" : "0 18px 60px rgba(53,80,255,0.55)" }}>
      <div style={{ fontFamily: H, fontSize: 70, color: WHITE, opacity: 1 - lin(m, 0, 0.3), whiteSpace: "nowrap" }}>CLICA NO LINK</div>
      <svg width={64} height={64} viewBox="0 0 48 48" style={{ opacity: 1 - lin(m, 0, 0.3) }}>
        <path d="M24 6 L24 38 M12 26 L24 38 L36 26" stroke={WHITE} strokeWidth={6} strokeLinecap="round" strokeLinejoin="round" fill="none" />
      </svg>
    </div>
  );
};

// ---------- cenas desenhadas ----------
// 2 · "existem centenas de pessoas que moram na tua cidade que sequer ouviram falar o nome da tua igreja"
const Cidade: React.FC<{ t: number }> = ({ t }) => {
  const cols = 6, rows = 6;
  const Q = [3, 8, 13, 16, 22, 27, 31, 34];
  return (
    <AbsoluteFill style={{ background: INK }}>
      <Glow cy={1100} o={0.25} />
      <Push t={t} a={11.1} b={17.5} k={0.1} oy={60}>
        <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", inset: 0 }}>
          {Array.from({ length: cols * rows }).map((_, i) => {
            const x = 165 + (i % cols) * 130, y = 780 + Math.floor(i / cols) * 112;
            const d = Math.hypot(x + 50 - 540, y + 50 - 1110);
            return <Casa key={i} x={x} y={y} on={ease(t, 11.12 + d / 1400, 0.3)} lit={ease(t, 11.78 + d / 1600, 0.15)} />;
          })}
          {Q.map((i, k) => {
            const x = 165 + (i % cols) * 130 + 50, y = 780 + Math.floor(i / cols) * 112 - 20;
            return <Balao key={k} x={x} y={y} p={pop(t, (k < 5 ? 14.46 : 15.64) + (k % 5) * 0.1)} />;
          })}
        </svg>
      </Push>
      {t < 14.4 ? (
        <Col top={300}>
          <Rise t={t} at={11.78} out={14.24} size={130}>CENTENAS</Rise>
          <Rise t={t} at={12.5} out={14.24} size={56} font={S} color={CYAN}>DE PESSOAS</Rise>
          <Rise t={t} at={13.76} out={14.24} size={56} font={S} color={CYAN}>NA TUA CIDADE</Rise>
        </Col>
      ) : (
        <Col top={300}>
          <Rise t={t} at={14.46} size={120}>SEQUER</Rise>
          <Rise t={t} at={14.7} size={120} color={CYAN}>OUVIRAM</Rise>
          <Rise t={t} at={15.64} size={50} font={S} stagger={0.08}>O NOME DA TUA IGREJA</Rise>
        </Col>
      )}
    </AbsoluteFill>
  );
};
// 3 · "você trabalha, trabalha, trabalha, trabalha" — a bateria descarrega um gomo a cada "trabalha"
const TRAB = [18.97, 19.61, 20.17, 20.65];
const Bateria: React.FC<{ t: number }> = ({ t }) => {
  const b = pop(t, 18.92);
  return (
    <AbsoluteFill style={{ background: INK }}>
      <Glow cy={1000} o={0.3} />
      <Push t={t} a={18.9} b={21.35} k={0.08} oy={52}>
        <div style={{ position: "absolute", left: 200, top: 860, width: 640, height: 300, transform: `scale(${b.toFixed(4)})` }}>
          <div style={{ position: "absolute", inset: 0, border: `14px solid ${WHITE}`, borderRadius: 44 }} />
          <div style={{ position: "absolute", right: -46, top: 95, width: 34, height: 110, background: WHITE, borderRadius: "0 16px 16px 0" }} />
          {[0, 1, 2, 3].map((k) => {
            const drain = sp(t, TRAB[3 - k], 24, 200);
            return <div key={k} style={{ position: "absolute", left: 32 + k * 146, top: 32, width: 130, height: 236, borderRadius: 18, background: k === 0 ? "#FF4D6A" : CYAN, opacity: 0.25 + 0.75 * (1 - drain), transform: `scaleY(${(1 - drain * 0.96).toFixed(4)})`, transformOrigin: "50% 100%" }} />;
          })}
        </div>
        <Col top={1220}>
          <div style={{ display: "flex", gap: 26 }}>
            {TRAB.map((p, k) => <div key={k} style={{ width: 70, height: 12, borderRadius: 6, background: t >= p ? CYAN : "rgba(255,255,255,0.18)" }} />)}
          </div>
        </Col>
      </Push>
      <Col top={460}>
        {TRAB.map((p, k) => (win(t, p - 0.1, TRAB[k + 1] ?? 99) ? <Rise key={k} t={t} at={p} out={TRAB[k + 1] !== undefined ? TRAB[k + 1] - 0.16 : undefined} size={130} color={k === 3 ? CYAN : WHITE}>TRABALHA</Rise> : null))}
      </Col>
    </AbsoluteFill>
  );
};
// 4 · "e as cadeiras da igreja continuam vazias" — auditório de poltronas vazias
const Cadeiras: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: INK }}>
    <Glow cy={1150} o={0.22} />
    <Push t={t} a={21.35} b={23.33} k={0.08} oy={65}>
      <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", inset: 0 }}>
        {[0, 1, 2, 3].map((r) => {
          const s = 0.8 + r * 0.17, n = 6 - (r > 1 ? 1 : 0), gap = 150 * s;
